void loadSpriteRankPalette(void) {
    if (spriteRank.palette) {
        return;
    }
    const char *error = NULL;
    spriteRank.palette = playdate->graphics->loadBitmapTable("sprites/sprite-rank", &error);
    if (error) {
        playdate->system->error("Unable to load bitmap table of sprite Rank: %s", error);
    }
}

